using DriveOS.Application.Abstractions.Authentication;using DriveOS.Application.Abstractions.Time;using DriveOS.SharedKernel.Auditing;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Diagnostics;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Interceptors;
internal sealed class CurriculumPedagogyAuditInterceptor(IClock clock,ICurrentUser currentUser):SaveChangesInterceptor
{public override InterceptionResult<int> SavingChanges(DbContextEventData e,InterceptionResult<int> r){Apply(e.Context);return base.SavingChanges(e,r);}public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData e,InterceptionResult<int> r,CancellationToken ct=default){Apply(e.Context);return base.SavingChangesAsync(e,r,ct);}private void Apply(DbContext? db){if(db is null)return;var now=clock.UtcNow;foreach(var x in db.ChangeTracker.Entries<IAuditableEntity>()){if(x.State==EntityState.Added&&x.Entity.CreatedAtUtc==default)x.Entity.SetCreatedAudit(now,currentUser.UserId);else if(x.State==EntityState.Modified)x.Entity.SetModifiedAudit(now,currentUser.UserId);}}}
